      { auteur: "Ibn Bashīr", avis: "La viande atteinte après cuisson est comme le beurre figé : on la mange après avoir lavé le bouillon.", statut: "non_precise" },
      { auteur: "Al-Madkhal", avis: "La volaille ébouillantée avant d'en laver le sang ne se purifie pas.", statut: "non_precise" },
      { auteur: "An-Nawādir", avis: "La volaille ébouillantée, puis lavée, se mange ; la tête flambée se mange si le sang a disparu.", statut: "non_precise" },
      { auteur: "Ibn Yūnus", avis: "Le poisson trouvé dans le ventre d'un oiseau mort se lave et se mange.", statut: "non_precise" }
